<script setup lang="ts">
import {ref,computed,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useI18n} from 'vue-i18n'
import Shell from '../components/Shell.vue'
import Chart from '../components/Chart.vue'
import EarthMap from '../components/EarthMap.vue'
import DetailsDrawer from '../components/DetailsDrawer.vue'
import {useMission} from '../store'
import {api,errorMessage} from '../api'
import {localized} from '../i18n'
import type {Bundle,ScoreResponse,OptimizeResponse,SensitivityResponse,Candidate} from '../types'
const route=useRoute();const router=useRouter();const {t,locale}=useI18n();const state=useMission()
const bundle=ref<Bundle>();const score=ref<ScoreResponse>();const optimization=ref<OptimizeResponse>();const sensitivity=ref<SensitivityResponse>();const error=ref('');const busy=ref(false);const loading=ref(false);const sensitiveBusy=ref(false);const selectedId=ref('');const copied=ref(false);const ready=ref(false);const samples=ref(500);const sensitivityError=ref('')
let timer:ReturnType<typeof setTimeout>|undefined;let controller:AbortController|undefined;let version=0;let loadVersion=0;let sensitiveVersion=0
const missionId=computed(()=>String(route.params.mission))
const selectedTasks=computed(()=>bundle.value?.tasks.filter(task=>state.taskIds.includes(task.id))||[])
const selectedCandidate=computed(()=>score.value?.candidates.find(c=>c.id===selectedId.value))
const candidateMap=computed(()=>Object.fromEntries((score.value?.candidates||[]).map(c=>[c.id,c])))
const invalidWeights=computed(()=>state.scheme==='custom'&&state.taskIds.reduce((sum,id)=>sum+(state.custom[id]??1),0)<=0)
const pointSites=computed(()=>bundle.value?.sites.filter(s=>s.lat!==null&&s.lon!==null)||[])
const coordinateLon=(lon:number)=>((lon+180)%360)-180
const percent=(x:number|null|undefined)=>x==null?'—':`${(x*100).toFixed(1)}%`
const showValue=(x:number|null|undefined)=>x==null?'—':x.toFixed(3)
const name=(item:{name:string;name_en?:string})=>localized(item,locale.value)
async function load(){
 const current=++loadVersion;ready.value=false;loading.value=true;error.value='';score.value=undefined;optimization.value=undefined;sensitivity.value=undefined;selectedId.value='';controller?.abort();version++
 try{const data=await api.bundle(missionId.value);if(current!==loadVersion)return;bundle.value=data;state.initialize(data,route.query);samples.value=data.settings.sensitivity.n_samples;ready.value=true;syncQuery();if(state.step===3)schedule()}catch(e){if(current===loadVersion)error.value=errorMessage(e)}finally{if(current===loadVersion)loading.value=false}
}
function syncQuery(){if(ready.value)void router.replace({query:state.query()})}
function schedule(){
 clearTimeout(timer);controller?.abort();version++;sensitiveVersion++;sensitivity.value=undefined;sensitiveBusy.value=false;sensitivityError.value='';selectedId.value=''
 if(state.step!==3){busy.value=false;return}
 score.value=undefined;optimization.value=undefined
 if(!state.taskIds.length||invalidWeights.value){busy.value=false;return}
 busy.value=true;timer=setTimeout(calculate,250)
}
async function calculate(){
 const current=++version;controller=new AbortController();error.value='';busy.value=true
 try{const request=state.request();const [s,o]=await Promise.all([api.score(request,controller.signal),api.optimize(request,controller.signal)]);if(current===version){score.value=s;optimization.value=o}}catch(e){if(current===version&&!controller.signal.aborted)error.value=errorMessage(e)}finally{if(current===version)busy.value=false}
}
async function runSensitivity(){
 const current=++sensitiveVersion;sensitiveBusy.value=true;sensitivityError.value=''
 try{const defaults=bundle.value!.settings.sensitivity;const result=await api.sensitivity(state.request(),samples.value,defaults.seed,defaults.alpha);if(current===sensitiveVersion)sensitivity.value=result}catch(e){if(current===sensitiveVersion)sensitivityError.value=errorMessage(e)}finally{if(current===sensitiveVersion)sensitiveBusy.value=false}
}
function go(step:number){state.step=step;window.scrollTo({top:180,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
async function share(){try{await navigator.clipboard.writeText(location.href);copied.value=true;setTimeout(()=>copied.value=false,1800)}catch{copied.value=false}}
watch(missionId,load,{immediate:true})
watch(()=>JSON.stringify([state.request(),state.step]),()=>{if(ready.value){syncQuery();schedule()}})
const canonical=(value:Record<string,unknown>)=>JSON.stringify(Object.keys(value).sort().map(k=>[k,value[k]]))
watch(()=>route.query,q=>{if(ready.value&&bundle.value&&canonical(q)!==canonical(state.query()))state.initialize(bundle.value,q)})
onBeforeUnmount(()=>{clearTimeout(timer);controller?.abort();version++;loadVersion++;sensitiveVersion++})
const marginalOption=computed(()=>({textStyle:{color:'#a9b7c5'},grid:{left:55,right:30,top:20,bottom:55},tooltip:{trigger:'axis' as const},xAxis:{type:'category' as const,name:t('kSites'),nameLocation:'middle' as const,nameGap:30,data:optimization.value?.marginal_curve.map(p=>p.k)},yAxis:{type:'value' as const,min:0,max:1,axisLabel:{formatter:(x:number)=>`${x*100}%`},splitLine:{lineStyle:{color:'#24303b'}}},series:[{type:'line' as const,data:optimization.value?.marginal_curve.map(p=>p.weighted_coverage),color:'#91ddba',symbolSize:8,areaStyle:{color:'rgba(145,221,186,.09)'}}]}))
const sensitiveOption=computed(()=>({textStyle:{color:'#a9b7c5'},grid:{left:75,right:25,top:15,bottom:30},tooltip:{trigger:'axis' as const},xAxis:{type:'value' as const,min:0,max:1,axisLabel:{formatter:(x:number)=>`${x*100}%`},splitLine:{lineStyle:{color:'#24303b'}}},yAxis:{type:'category' as const,inverse:true,data:sensitivity.value?.frequencies.slice(0,10).map(p=>candidateMap.value[p.candidate_id]?.name||p.candidate_id)},series:[{type:'bar' as const,data:sensitivity.value?.frequencies.slice(0,10).map(p=>p.frequency),itemStyle:{color:'#91bfe1',borderRadius:2},barWidth:14}]}))
function select(c:Candidate){selectedId.value=c.id}
</script>
<template><Shell>
 <div v-if="loading" class="loading-state"><span class="spinner"></span>{{t('loading')}}…</div>
 <template v-if="bundle&&!loading"><div class="mission-head"><router-link to="/" class="breadcrumb">← {{t('home')}}</router-link><div class="mission-title-row"><div><span class="eyebrow">MISSION / {{missionId.toUpperCase()}}</span><h1>{{name(bundle.mission)}}</h1><p>{{locale==='en'?bundle.mission.goal_en:bundle.mission.goal}}</p></div><div class="mini-planet" :class="missionId" aria-hidden="true"></div></div><div class="brief"><span class="eyebrow">{{t('nasaBasis')}}</span><p>{{locale==='en'?bundle.mission.summary_en:bundle.mission.summary}}</p><div class="inline-links"><a v-for="link in bundle.mission.nasa_sources" :key="link.url" :href="link.url" target="_blank" rel="noopener">{{link.title}} ↗</a></div></div></div>
 <div class="wizard-nav"><button v-for="(key,index) in ['step1','step2','step3']" :key="key" :disabled="index>0&&!state.taskIds.length" :class="{current:state.step===index+1,done:state.step>index+1}" @click="go(index+1)"><span>{{state.step>index+1?'✓':`0${index+1}`}}</span>{{t(key)}}<i v-if="index<2">→</i></button></div>
 <div v-if="error" role="alert" class="error-panel">{{t('error')}}: {{error}} <button @click="ready?calculate():load()">{{t('retry')}}</button></div>
 <section v-if="state.step===1" class="section wizard-section"><div class="section-heading"><div><span class="eyebrow">01 / DEFINE THE TEST</span><h2>{{t('step1')}}</h2></div><div class="selection-tools"><span>{{t('selected')}} {{state.taskIds.length}} / {{bundle.tasks.length}}</span><button @click="state.taskIds=bundle!.tasks.map(task=>task.id)">{{t('all')}}</button><button @click="state.taskIds=[]">{{t('none')}}</button></div></div><p class="small muted">{{t('rankNote')}}</p><div class="task-grid"><article v-for="task in bundle.tasks" :key="task.id" class="task-card" :class="{selected:state.taskIds.includes(task.id)}"><label class="task-select"><input type="checkbox" :checked="state.taskIds.includes(task.id)" @change="state.toggle(task.id)"><span class="mono task-id">{{task.id}}</span><span class="check-mark" aria-hidden="true">{{state.taskIds.includes(task.id)?'✓':'＋'}}</span><h3>{{name(task)}} <sup v-if="task.manual_adjust">*</sup></h3><p>{{task.verify}}</p></label><div class="task-meta"><span>{{t('ranking')}} <b>{{task.tech_gap?.label||'—'}}</b></span><span>{{t('weight')}} <b class="mono">{{percent(task.weights.roc)}}</b></span><span>{{task.features.length}} {{t('features')}}</span></div><a class="source-link" :href="task.nasa_url" target="_blank" rel="noopener">{{task.nasa_basis}} ↗</a><div class="badges"><span v-if="task.features.some(f=>[...f.planet_data,...f.earth_data].some(s=>s.official))" class="badge official">✓ {{t('official')}}</span><span v-if="task.features.some(f=>[...f.planet_data,...f.earth_data].some(s=>!s.official))" class="badge supplement">＋ {{t('supplement')}}</span></div><p v-if="task.manual_adjust" class="small warning">* {{task.manual_adjust.reason}}</p><details><summary>{{t('expand')}}</summary><div v-for="feature in task.features" :key="feature.id" class="feature-list"><strong>{{name(feature)}}</strong><span class="mono">{{feature.type}} · {{feature.compare_mode}}</span><span v-if="feature.out_of_earth_range" class="warning">{{t('not_reproducible')}}</span><span v-if="feature.earth_proxy" class="badge">{{t('proxy')}}</span><p v-for="note in feature.notes" :key="note" class="small muted">{{note}}</p></div><ul><li v-for="note in task.notes" :key="note">{{note}}</li></ul></details></article></div><div class="step-actions"><span v-if="!state.taskIds.length" class="warning">{{t('noTasks')}}</span><button class="button primary" :disabled="!state.taskIds.length" @click="go(2)">{{t('next')}} →</button></div>
 <div class="limits-section"><span class="eyebrow">THE BOUNDARIES</span><h2>{{t('allLimits')}}</h2><div class="table-scroll"><table><thead><tr><th>{{t('condition')}}</th><th>{{t('requirement')}}</th><th>{{t('reproducible')}}</th><th>{{t('handling')}}</th></tr></thead><tbody><tr v-for="limit in bundle.limits" :key="limit.condition"><th>{{limit.condition}}</th><td>{{limit.planet}}</td><td>{{limit.reproducible}}</td><td>{{limit.handling}}</td></tr></tbody></table></div></div>
 <div v-if="bundle.constraints.length" class="limits-section"><h2>{{t('constraints')}}</h2><div class="table-scroll"><table><thead><tr><th>{{t('condition')}}</th><th>{{t('requirement')}}</th><th>{{t('reproducible')}}</th></tr></thead><tbody><tr v-for="c in bundle.constraints" :key="c.condition"><th>{{c.condition}}</th><td>{{c.requirement}}</td><td>{{c.earth_analog}}</td></tr></tbody></table></div></div>
 </section>
 <section v-else-if="state.step===2" class="section wizard-section"><div class="section-heading"><div><span class="eyebrow">02 / SET YOUR DESTINATION</span><h2>{{t('step2')}}</h2></div></div><p class="notice">◈ {{t('targetDemo')}}</p><div v-if="pointSites.length" class="planet-coordinates"><svg viewBox="0 0 720 230" role="img" :aria-label="t('planetMapNote')"><defs><pattern id="grid" width="60" height="38.333" patternUnits="userSpaceOnUse"><path d="M 60 0 L 0 0 0 38.333" fill="none" stroke="#2e3943" stroke-width=".6"/></pattern></defs><rect width="720" height="230" fill="url(#grid)"/><g v-for="site in pointSites" :key="site.id" :transform="`translate(${(coordinateLon(site.lon!)+180)*2},${(90-site.lat!)*230/180})`"><circle r="5" :fill="site.id===state.siteId?'#91ddba':'#8195a8'"/><text x="9" y="4" fill="#c5d0da" font-size="11">{{site.name_en}}</text></g></svg><p class="small muted">{{t('planetMapNote')}}</p></div><fieldset class="site-grid"><legend class="sr-only">{{t('step2')}}</legend><label v-for="site in bundle.sites" :key="site.id" class="site-card" :class="{selected:state.siteId===site.id}"><input v-model="state.siteId" type="radio" name="target-site" :value="site.id"><span class="site-radio" aria-hidden="true"></span><span class="eyebrow">{{site.coords_status==='todo'?'COORDINATES / TODO':site.coords_status.toUpperCase()}}</span><h3>{{name(site)}}</h3><p class="small">{{locale==='en'?site.description_en:site.description}}</p><span class="mono small" v-if="site.lat!==null&&site.lon!==null">{{site.lat}}°, {{coordinateLon(site.lon)}}°</span><span v-else class="small muted">{{t('noCoords')}}</span><p class="small muted">{{t('source')}}: {{site.source}}</p></label></fieldset><div class="step-actions"><button class="button" @click="go(1)">← {{t('back')}}</button><button class="button primary" @click="go(3)">{{t('run')}} →</button></div></section>
 <section v-else class="results section"><div v-if="score?.uses_placeholder||optimization?.uses_placeholder" role="status" class="demo-banner">◈ {{t('placeholder')}}<small>{{t('seedNote')}}</small></div><div class="result-topline"><div><span class="eyebrow">03 / EARTH ANALOGS</span><h2>{{t('step3')}}</h2></div><button class="text-button" @click="share">{{copied?t('copied'):t('share')}} ↗</button></div><div class="controls-panel"><label class="tau-control">{{t('tau')}} <strong class="mono">{{state.tau.toFixed(2)}}</strong><input v-model.number="state.tau" type="range" min="0.05" max="1" step="0.01"></label><label>{{t('scheme')}}<select v-model="state.scheme"><option value="roc">{{t('roc')}}</option><option value="rank_sum">{{t('rank_sum')}}</option><option value="custom">{{t('custom')}}</option></select></label><label class="switch-label"><input v-model="state.excludeKnown" type="checkbox"><span>{{t('exclude')}}</span></label><div v-if="state.scheme==='custom'" class="custom-weights"><label v-for="task in selectedTasks" :key="task.id">{{task.id}} <span>{{state.custom[task.id]}}</span><input v-model.number="state.custom[task.id]" type="range" min="0" max="10" step="0.1"></label></div></div><p v-if="invalidWeights" class="warning" role="alert">{{t('invalidWeights')}}</p><p v-if="!state.taskIds.length" class="warning">{{t('noTasks')}}</p><div v-if="busy" class="loading-state" role="status"><span class="spinner"></span>{{t('calculating')}}…</div>
 <template v-if="score"><p v-for="warning in score.warnings" :key="warning" class="notice">{{warning}}</p><div class="result-summary"><div><span>{{t('selected')}}</span><strong>{{selectedTasks.length}} <small>{{t('step1')}}</small></strong></div><div><span>{{t('candidate')}}</span><strong>{{score.candidates.length}} <small>{{t('sitesUnit')}}</small></strong></div><div><span>{{t('weight')}}</span><div class="weight-chips"><span v-for="(w,id) in score.weights" :key="id">{{id}} <b>{{percent(w)}}</b></span></div></div></div>
 <section class="result-section"><div class="section-heading"><h2>{{t('overall')}}</h2><span class="eyebrow">{{score.candidates.length}} / {{t('sitesUnit')}}</span></div><div class="ranking-map"><div class="overall-list"><button v-for="(candidate,index) in score.candidates" :key="candidate.id" class="ranking-row" @click="select(candidate)"><span class="rank-index mono">{{String(index+1).padStart(2,'0')}}</span><span class="ranking-name">{{candidate.name}}<small v-if="candidate.known_analog">{{t('known')}}</small></span><span class="score-track"><i :style="{width:percent(candidate.overall)}"></i></span><strong class="mono">{{showValue(candidate.overall)}}</strong><span>↗</span></button></div><EarthMap :candidates="score.candidates" :settings="bundle.settings.map" :similar-cutoff="bundle.settings.similar_cutoff" :different-cutoff="bundle.settings.different_cutoff" @select="selectedId=$event"/></div><div class="result-evidence"><span>{{t('nasaBasis')}}:</span><a v-for="link in bundle.mission.nasa_sources" :key="link.url" :href="link.url" target="_blank" rel="noopener">{{link.title}} ↗</a></div></section>
 <section class="result-section"><h2>{{t('taskRanking')}}</h2><div class="task-rank-grid"><article v-for="rank in score.task_rankings" :key="rank.task_id" class="panel"><div class="panel-heading"><span class="eyebrow">{{rank.task_id}}</span><h3>{{name(bundle.tasks.find(task=>task.id===rank.task_id)!)}}</h3></div><button v-for="(row,index) in rank.rankings" :key="row.candidate_id" class="task-rank-row" @click="selectedId=row.candidate_id"><span class="mono muted">{{String(index+1).padStart(2,'0')}}</span><span>{{candidateMap[row.candidate_id]?.name}}</span><span class="score-track"><i :style="{width:percent(row.score)}"></i></span><b class="mono">{{showValue(row.score)}}</b></button><a :href="bundle.tasks.find(task=>task.id===rank.task_id)!.nasa_url" target="_blank" rel="noopener" class="source-link">{{t('nasaBasis')}} ↗</a></article></div></section>
 <section v-if="optimization" class="result-section"><div class="section-heading"><h2>{{t('minimum')}}</h2><a :href="bundle.mission.nasa_sources[0]!.url" target="_blank" rel="noopener" class="source-link">{{t('nasaBasis')}} ↗</a></div><div class="network-summary"><div><span class="big-number">{{optimization.minimum_sites}}</span><span>{{t('sitesUnit')}}</span></div><div><span class="big-number">{{optimization.covered_tasks.length}}<small>/{{optimization.total_tasks}}</small></span><span>{{t('covers')}}</span></div><div class="network-sites"><button v-for="id in optimization.selected" :key="id" class="button" @click="selectedId=id">{{candidateMap[id]?.name}} ↗</button></div></div><p v-if="optimization.uncoverable.length" class="notice">{{t('uncoverable')}}: {{optimization.uncoverable.join(', ')}}</p><h3>{{t('coverage')}}</h3><div class="table-scroll"><table><thead><tr><th>{{t('step1')}}</th><th v-for="id in optimization.selected" :key="id">{{candidateMap[id]?.name}}</th><th>{{t('covers')}}</th></tr></thead><tbody><tr v-for="row in optimization.coverage" :key="row.task_id"><th>{{row.task_id}}</th><td v-for="id in optimization.selected" :key="id"><span v-if="row.covered_by.some(c=>c.candidate_id===id)" class="similar mono">✓ {{showValue(row.covered_by.find(c=>c.candidate_id===id)?.score)}}</span><span v-else class="muted">—</span></td><td :class="row.covered_by.length?'similar':'warning'">{{row.covered_by.length?'✓':t('uncoverable')}}</td></tr></tbody></table></div><div class="analysis-grid"><article class="panel"><h3>{{t('marginal')}}</h3><Chart :option="marginalOption" :label="t('marginal')"/></article><article class="panel"><h3>{{t('sensitivity')}}</h3><p class="muted small">{{t('sensitivityIntro')}}</p><div class="sensitivity-controls"><label>{{t('samples')}} <input v-model.number="samples" type="number" min="1" max="1000"></label><button class="button" :disabled="sensitiveBusy||samples<1||samples>1000||!Number.isInteger(samples)" @click="runSensitivity">{{t(sensitiveBusy?'calculating':'runSensitivity')}}</button></div><p v-if="sensitivityError" role="alert" class="warning">{{sensitivityError}}</p><Chart v-if="sensitivity" :option="sensitiveOption" :label="t('frequency')"/><p v-if="sensitivity" class="small mono muted">n={{sensitivity.n_samples}} · seed={{sensitivity.seed}} · k={{sensitivity.k}}</p></article></div></section>
 <section class="result-section robustness"><div><h3>{{t('robustness')}}</h3><p class="muted small">{{score.robustness.status}}</p></div><span class="mono">{{t('spearman')}}: {{score.robustness.spearman?.toFixed(3)??'—'}}</span><router-link to="/method">{{t('method')}} ↗</router-link></section>
 </template><div class="step-actions"><button class="button" @click="go(2)">← {{t('back')}}</button></div>
 </section>
 <DetailsDrawer v-if="selectedCandidate" :candidate="selectedCandidate" :tasks="selectedTasks" :limits="bundle.limits" :site-id="state.siteId" :mission="missionId" @close="selectedId=''"/>
 </template><div v-if="error&&!bundle" class="error-panel" role="alert">{{error}} <button @click="load">{{t('retry')}}</button></div>
</Shell></template>
